 @Test void uomLayoutUsesNativeColumnNamesAndRollsBack()throws Exception{
  var jdbc=InventoryOpeningLiveTest.jdbc();var u=InventoryOpeningLiveTest.user(jdbc);u.setUserName(jdbc.queryForObject("SELECT UserName FROM UserAccount WHERE Id=?",String.class,u.getId()));var context=mock(CurrentUserContext.class);when(context.requireAccountingUser()).thenReturn(u);var rights=mock(DesktopReportRights.class);var repo=new DesktopInventoryGridLayoutRepository(jdbc);var service=new DesktopInventoryGridLayoutService(repo,context,rights,directory.toString());
  String name="InvDeffrmItemUomSchedule_grdfrm_"+u.getUserName();var file=directory.resolve(name);var columns=new ArrayList<InventoryGridColumn>();for(String key:List.of("Item","Schedule Unit","Equivalent","QtyEquivalent","BaseRateUom","BasePackUom","BaseSecondaryUom","Active")){var c=new InventoryGridColumn();c.key=key;c.position=columns.size();c.width=130;c.visible=!key.equals("BaseSecondaryUom");columns.add(c);}
  String sql="SELECT Id,ScreenName,Layout,EntryDate,EntryUserId,OrganizationId,CompanyId,CONVERT(varchar(max),LayoutFile,2) FileHex,CONVERT(nvarchar(max),LayoutFileXml) FileXml FROM GridLayout ORDER BY Id";var before=jdbc.queryForList(sql);var tx=new TransactionTemplate(new DataSourceTransactionManager(jdbc.getDataSource()));tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_SERIALIZABLE);
  tx.execute(status->{try{assertEquals(8,service.save("uom-schedules",columns).size());var saved=service.load("uom-schedules");assertFalse(saved.stream().filter(c->c.key.equals("BaseSecondaryUom")).findFirst().orElseThrow().visible);assertTrue(Files.readString(file).contains("ID=\"Schedule Unit\""));assertTrue(repo.exists(u,name));service.remove("uom-schedules");assertFalse(Files.exists(file));service.save("uom-schedules",columns);return null;}catch(Exception ex){throw new RuntimeException(ex);}finally{status.setRollbackOnly();}});
  assertFalse(Files.exists(file));assertEquals(before,jdbc.queryForList(sql));verify(rights,atLeastOnce()).require(u,115,"View");verify(rights,never()).require(u,111,"View");Files.writeString(Path.of("migration/inventory/evidence/uom-layout-rollback.txt"),"UOM Schedule: all8 source column keys including Item and Schedule Unit; own115 rights, native user/form/grid filename, visibility and save/load/remove verified. Original GridLayout rows and temporary file restored after rollback. No C:/SCS writes. Native Janus rendering and browser persistence pending.\n");
 }

